import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases ---
  it.todo("charges only the 5 G processing fee for an empty item list — premium 5 G");
  it.todo("quotes a plain sword for a new customer — 100 G base + 10 G first insurance + 5 G fee = 115 G");
  it.todo("quotes a plain amulet for a new customer — 60 G base + 6 G first insurance + 5 G fee = 71 G");
  it.todo("quotes a plain staff for a new customer — 80 G base + 8 G first insurance + 5 G fee = 93 G");
  it.todo("quotes a plain potion for a new customer — 40 G base + 4 G first insurance + 5 G fee = 49 G");

  // --- Components and the building block of 3 alike ---
  it.todo("charges 25 G base per component — 2 runes → 50 G base premium");
  it.todo("applies the block price to exactly 3 alike components — 3 runes → 60 G base premium");
  it.todo("does not apply the block to 4 runes — 4 runes → 100 G base premium");
  it.todo("applies one block plus singles for 7 runes — 7 runes → 175 G base premium");
  it.todo("treats only identical types as alike — 2 runes + 1 moonstone → 75 G base premium (no block)");
  it.todo("forms a separate block per component type — 3 runes + 3 moonstones → 120 G base premium");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium — cursed sword → 150 G base");
  it.todo("adds a 30 % surcharge at enchantment exactly 5 — sword enchantment 5 → 130 G base");
  it.todo("adds no high-enchantment surcharge at enchantment 4 — sword enchantment 4 → 100 G base");
  it.todo("stacks curse and high enchantment on the same item — cursed sword enchantment 5 → 180 G base");
  it.todo("applies the curse surcharge only to the cursed item, not the policy total — cursed sword + plain amulet → 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("grants the 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("grants no loyalty discount at 1 year with MHPCO");
  it.todo("adds the 10 % first insurance surcharge to every quote, regardless of customer history");
  it.todo("applies the 15 % follow-up discount to the customer's second quote but not the first");

  // --- Rounding ---
  it.todo("rounds a premium up in the MHPCO's favor — 197.5 G → 198 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed sword — 100 base + 50 curse + 10 first insurance + 5 fee = 165 G");
  it.todo("quotes a long-standing customer's second contract with a cursed sword enchantment 7 — 160 G");

  // --- Claims: standard reimbursement ---
  it.todo("reimburses damage in full minus a 100 G deductible — steel sword enchantment 3, damage 500 G → payout 400 G");
  it.todo("reimburses component damage minus the deductible — rune damage 200 G → payout 100 G");
  it.todo("applies the 100 G deductible once per damaged item — sword 500 G + amulet 300 G → payout 600 G");

  // --- Claims: special clauses ---
  it.todo("reimburses damage to items with enchantment ≥ 8 at 50 % — steel sword enchantment 9, damage 1000 G → payout 400 G");
  it.todo("reimburses dragon-material damage in full — dragon sword enchantment 5, damage 800 G → payout 700 G");
  it.todo("lets the 50 % rule win when both clauses apply — dragon sword enchantment 9, damage 1000 G → payout 400 G");
  it.todo("applies the 50 % clause at exactly enchantment 8 — dragon sword enchantment 8, damage 1000 G → payout 400 G");

  // --- Claims: cap ---
  it.todo("reports the remaining cap of twice the insurance sum after a claim — sword policy, damage 500 G → remainingCap 1600 G");
  it.todo("caps successive claims at twice the insurance sum — sword, two 1500 G claims → 1400 G then 600 G, remainingCap 0");
  it.todo("sums insurance values across items for the cap — sword + amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values — cursed sword → cap 2000 G");
  it.todo("excludes the block discount from the insurance sum — sword + 3 runes → insurance sum 1750 G, cap 3500 G");

  // --- Multiple items of the same type ---
  it.todo("sums the insurance value of two swords — insurance sum 2000 G, cap 4000 G");
  it.todo("treats each damage entry of the same type as a separate damage with its own deductible");

  // --- Payout rounding ---
  it.todo("rounds a payout down in the MHPCO's favor — 350.5 G → 350 G");

  // --- Errors ---
  it.todo("rejects a quote containing an item with an unknown type");
  it.todo("rejects a claim whose damaged item is not part of the policy");
  it.todo("rejects a claim with more damage entries of a type than the policy covers");
  it.todo("rejects a claim with a negative damage amount");

  // --- CLI ---
  it.todo("writes {results: [...]} to stdout for a scenario read from stdin");
  it.todo("exits with a non-zero status and writes to stderr when the scenario is invalid");
});

