export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResults = {
  results: unknown[];
};

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const PROCESSING_FEE = 5;

// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
// 115.00000000000001); snap to cent precision so only genuine fractions round up.
const roundUpInMHPCOsFavour = (amount: number): number =>
  Math.ceil(Number(amount.toFixed(6)));

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

// Only exactly 3 *alike* components form a block, but no test yet distinguishes
// "3 alike" from "3 items", so the check is still on the whole item count.
// The 4-runes and 3-runes-+-3-moonstones tests will force the grouping.
const policyBasePremiumOf = (items: Item[]): number =>
  items.length === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : sum(items.map(basePremiumOf));

const quote = (step: QuoteStep): number => {
  const policyBasePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return roundUpInMHPCOsFavour(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
};

