  const policyBasePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return roundUpInMHPCOsFavour(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
};

