// whole table sums without sign-juggling at the call site.
const POLICY_MODIFIERS: {
  appliesTo: (context: QuoteContext) => boolean;
  rate: number;
}[] = [
  { appliesTo: alwaysApplies, rate: 0.1 }, // first insurance surcharge
  { appliesTo: isLoyal, rate: -0.2 },
  { appliesTo: isFollowUpContract, rate: -0.15 },
