const capOf = (policy: QuoteStep): number =>
  insuranceSumOf(policy.items) * CAP_MULTIPLE_OF_INSURANCE_SUM;

export const runScenario = (scenario: Scenario): ScenarioResults => {
  // A policy's cap is consumed by every claim against it, so what is left has
  // to survive from one step to the next.
  const remainingCapByPolicy = new Map<number, number>();

  return {
    results: scenario.steps.map((step, precedingSteps) => {
      if (step.op === "claim") {
        const policy = policyOf(scenario, step);
        const result = claim(
          step,
          policy,
          remainingCapByPolicy.get(step.policy) ?? capOf(policy),
        );

        remainingCapByPolicy.set(step.policy, result.remainingCap);

        return result;
      }

      return {
        // Steps, not quotes: with only quote-then-claim scenarios under test the
        // two counts agree. A claim before a quote would make them diverge, and
        // that is the deferred test's job to pin down.
        premium: quote(step, {
          customer: scenario.customer,
          precedingQuotes: precedingSteps,
        }),
      };
    }),
  };
};

